const item = $input.first().json || {};

function hasViolation(obj, depth = 0) {
  if (depth > 6 || obj === null || obj === undefined) return false;
  if (typeof obj === "boolean") return obj;
  if (typeof obj === "string") {
    const t = obj.toLowerCase();
    return (
      t.includes("violation") ||
      t.includes("blocked") ||
      t.includes("unsafe") ||
      t.includes("redact")
    );
  }
  if (typeof obj === "number") return false;
  if (Array.isArray(obj)) return obj.some((v) => hasViolation(v, depth + 1));

  const directKeys = [
    "hasViolation",
    "isViolation",
    "violated",
    "blocked",
    "isBlocked",
    "unsafe",
    "redacted",
    "guardrailTriggered",
    "piiDetected",
  ];

  for (const key of directKeys) {
    if (key in obj && typeof obj[key] === "boolean") return obj[key];
  }

  if (
    "violations" in obj &&
    Array.isArray(obj.violations) &&
    obj.violations.length > 0
  )
    return true;
  if ("matches" in obj && Array.isArray(obj.matches) && obj.matches.length > 0)
    return true;

  return Object.values(obj).some((v) => hasViolation(v, depth + 1));
}

return [
  {
    json: {
      ...item,
      hasGuardrailViolation: hasViolation(item),
      guardrailStage: "input",
    },
  },
];

